import org.slf4j.MDC

class FooKt1 {
    fun bad() {
        MDC.put("levelKey1", "levelName1") // violation
        MDC.put("levelKey2", "levelName2") // violation
    }
}

import org.slf4j.MDC

class FooKt2 {
    fun good() {
        try {
            MDC.put("levelKey1", "levelName1")
            MDC.put("levelKey2", "levelName2")
        } finally {
            MDC.clear()
        }
    }
}

import org.slf4j.MDC

class FooKt3 {
    fun good() {
        MDC.put("levelKey1", "levelName1")
        MDC.remove("levelKey1")
    }
}

import org.slf4j.MDC

class Issue653Kt {

    companion object {
        const val CODE = "code"
    }

    fun handle(detail: String, code: String): String {
        try {
            setMDC(code, detail)
            return doSomething()
        } finally {
            clearMDC()
        }
    }

    private fun doSomething(): String = "OK"

    private fun setMDC(code: String, detail: String) {
        MDC.put(CODE, code) // false positive
        MDC.put("detail", detail) // false positive
        MDC.put("forgotten", "nada") // bad, not removed
    }

    private fun clearMDC() {
        MDC.remove(CODE)
        MDC.remove("detail")
    }
}

// Note: no import of org.slf4j.MDC here

object MDC {
    fun put(key: String, value: String) {}
    fun remove(key: String) {}
}

class LocalMdcShadowingTest {
    fun badLookingButLocal() {
        MDC.put("k1", "v1") // should not be flagged, not org.slf4j.MDC
    }
}
